$tabla=$tablas[$tipo];
$st=$conn->prepare("SELECT * FROM {$tabla} WHERE id=? AND eliminado_at IS NULL LIMIT 1"); $st->bind_param('i',$id); $st->execute(); $r=$st->get_result()->fetch_assoc();
